# Generated from ../en.json. Do not edit.
installer_template() {
	case "$1" in
		'account.username') printf '%s' 'Sign-in username' ;;
		'cancelled') printf '%s' $'\nInstallation cancelled.\n' ;;
		'check.build') printf '%s' 'Docker build support' ;;
		'check.commands') printf '%s' 'Required system commands' ;;
		'check.compose') printf '%s' 'Docker Compose v2' ;;
		'check.connection') printf '%s' 'Docker daemon connection' ;;
		'check.disk') printf '%s' 'Installation free space check' ;;
		'check.docker') printf '%s' 'Docker command' ;;
		'check.files') printf '%s' 'Required release files' ;;
		'check.fresh') printf '%s' 'No existing SPH configuration' ;;
		'check.linux') printf '%s' 'Linux containers' ;;
		'check.memory') printf '%s' 'Docker memory check' ;;
		'check.network') printf '%s' 'Connection prerequisites (public DNS when selected)' ;;
		'check.ports') printf '%s' 'Docker host port allocation' ;;
		'check.resources') printf '%s' 'No conflicting SPH containers or volumes' ;;
		'check.settings') printf '%s' 'Compose configuration' ;;
		'check.workspace') printf '%s' 'Docker access to installation files and folder' ;;
		'check.write') printf '%s' 'Installation folder: create, write, rename, delete and protect files' ;;
		'complete') printf '%s' 'Installation completed: {1}/' ;;
		'complete.notice') printf '%s' 'Sign in with the username and password you entered. Keep .env secure and back it up separately from the database.' ;;
		'configuration.failed') printf '%s' 'Setup input or configuration saving failed. Check the preceding message and folder write permissions. An existing .env will not be overwritten.' ;;
		'configuration.saved') printf '%s' $'Configuration saved. Secrets were not displayed. Keep .env safe and back it up separately from the database.\n' ;;
		'confirm.continue') printf '%s' 'Continue installation?' ;;
		'confirm.no') printf '%s' 'Cancel' ;;
		'confirm.yes') printf '%s' 'Continue' ;;
		'connection.acmeAgreement') printf '%s' 'Read the Let'\''s Encrypt Subscriber Agreement at https://letsencrypt.org/repository/. Type YES to agree and continue: ' ;;
		'connection.acmeEmail') printf '%s' 'Let'\''s Encrypt account contact email' ;;
		'connection.internalHttpExample') printf '%s' 'Example: {1}. This is only an example; enter this computer'\''s actual private IPv4 address.' ;;
		'connection.internalHttpNotice') printf '%s' 'All traffic, including passwords, session cookies, and employee and asset data, is unencrypted. Reserve the server'\''s private IPv4 address and allow access only from devices on the local area network. No server certificate is required.' ;;
		'connection.internalHttpsExample') printf '%s' 'Example: https://sph-server. This is only an example; enter this computer'\''s actual hostname.' ;;
		'connection.internalTrustNotice') printf '%s' 'The installer exports the public CA root certificate to .runtime/ca/root.crt. An administrator must verify its identity on the server, securely distribute it to each client device, and configure it as trusted.' ;;
		'connection.ipAddress') printf '%s' 'Select this computer'\''s private IPv4 address' ;;
		'connection.mode') printf '%s' 'Connection mode' ;;
		'connection.modeInternal') printf '%s' 'Internal HTTPS' ;;
		'connection.modeInternalHttp') printf '%s' 'Internal HTTP' ;;
		'connection.modeLocal') printf '%s' 'Local only' ;;
		'connection.modePublic') printf '%s' 'Public domain' ;;
		'connection.notice') printf '%s' 'Choose a connection mode. Local only is available on this PC; internal HTTP sends unencrypted traffic over the local area network; internal HTTPS requires CA root certificate trust on each client. A public domain requires public DNS, inbound TCP 80 and 443, an ACME contact email address, and acceptance of the Let'\''s Encrypt subscriber agreement.' ;;
		'connection.port') printf '%s' 'Docker host web port' ;;
		'connection.url') printf '%s' 'Application URL' ;;
		'employment.contract') printf '%s' 'Contract' ;;
		'employment.employeeCode') printf '%s' 'Employee code (10–64 letters or numbers)' ;;
		'employment.hireDate') printf '%s' 'Hire date (YYYY-MM-DD)' ;;
		'employment.notice') printf '%s' 'Change these employment details later in Employees.' ;;
		'employment.partTime') printf '%s' 'Part Time' ;;
		'employment.regular') printf '%s' 'Regular' ;;
		'employment.temporary') printf '%s' 'Temporary' ;;
		'employment.type') printf '%s' 'Employment type' ;;
		'error.acmeDeclined') printf '%s' 'The Let'\''s Encrypt Subscriber Agreement was not accepted. No configuration was saved.' ;;
		'error.build') printf '%s' 'Service image build failed. The underlying cause could not be determined safely. Check network access, Docker disk space and the complete release files.' ;;
		'error.buildSupport') printf '%s' 'Docker buildx is unavailable. Install or repair the Docker Buildx plugin and verify docker buildx version succeeds.' ;;
		'error.caExport') printf '%s' 'The internal CA public certificate could not be exported. Keep the gateway data volume and retry the export. Never distribute the CA private key.' ;;
		'error.cancelled') printf '%s' 'Installation cancelled. No application settings or database data were changed.' ;;
		'error.cleanup') printf '%s' 'Could not prepare or replace .env to remove initial setup credentials. Check write permissions and whether .env.install-clean already exists. These files may contain secrets; keep them protected.' ;;
		'error.commands') printf '%s' 'Required system commands are unavailable. Use a complete Bash environment with mkdir, mktemp, chmod, mv, rm, rmdir, cat, grep, sleep, id, uname and awk available on PATH.' ;;
		'error.compose') printf '%s' 'Docker responded, but docker compose version failed. Install or repair Docker Compose v2 and confirm that docker compose version works in this terminal.' ;;
		'error.composeConfig') printf '%s' 'Docker Compose could not validate the saved configuration. Preserve .env and check the release files and connection settings. Do not share secrets.' ;;
		'error.docker') printf '%s' 'Docker failed while checking existing containers or storage. The underlying cause could not be determined safely. Check that Docker is running and that your account can access it.' ;;
		'error.dockerConnection') printf '%s' 'The docker info command failed: Docker could not be accessed. Check that Docker Desktop or the Docker daemon is running, the Docker context points to the intended server, and your account has access.' ;;
		'error.dockerRequired') printf '%s' 'The docker command was not found. Install Docker with Docker Compose, then reopen the terminal and start Docker before running this installer.' ;;
		'error.existingConfiguration') printf '%s' 'An existing .env was found in the installation folder. This installer is for a new installation and cannot overwrite existing configuration. Keep .env and database storage.' ;;
		'error.existingResources') printf '%s' 'SPH containers or data volumes already exist. A new installation was stopped to protect existing data. Keep these resources.' ;;
		'error.gatewayConfig') printf '%s' 'The gateway configuration could not be generated. Keep the saved .env file and check its connection settings before recovery.' ;;
		'error.health') printf '%s' 'The local API or application did not return the expected response. Check gateway, frontend, API and database service status and the HTTP_PORT setting.' ;;
		'error.initialCredentials') printf '%s' 'Initial setup credentials still remain in a service. Installation cannot be marked complete. Remove INITIAL_ADMIN_* settings and recreate the affected services; do not delete database storage.' ;;
		'error.inspectCredentials') printf '%s' 'Could not inspect service configuration to verify removal of initial setup credentials. Installation cannot be marked complete. Check Docker access and database/API service status.' ;;
		'error.interrupted') printf '%s' 'Installation was interrupted by a signal. Saved configuration and database storage may remain.' ;;
		'error.linuxContainers') printf '%s' 'The Docker daemon is not using Linux containers. Switch Docker Desktop to Linux containers or select a Linux Docker daemon.' ;;
		'error.migration') printf '%s' 'Could not confirm successful completion of the database migration job. Check the migration service status and database connectivity. Keep .env and database storage.' ;;
		'error.networkPreflight') printf '%s' 'The public domain did not resolve. Configure public DNS before retrying, and keep the saved .env file for recovery.' ;;
		'error.permissions') printf '%s' 'Could not secure the permissions of a configuration file. Check folder ownership, write permissions and security software.' ;;
		'error.ports') printf '%s' 'Docker could not allocate the required host ports ({1}). Check for another service, reserved ports or an unavailable host IP. Stop the conflicting service or choose another web port. Preserve .env if it was saved.' ;;
		'error.preflight') printf '%s' 'Required pre-installation checks failed. Resolve the issues above and run the installer again. Existing settings and data have been preserved.' ;;
		'error.pull') printf '%s' 'Could not download the node:22-alpine setup image. The underlying cause could not be determined safely. Check registry connectivity, proxy settings and Docker disk space; retry docker pull node:22-alpine.' ;;
		'error.refreshApi') printf '%s' 'Could not recreate the API service without initial setup credentials, or it did not become healthy within 300 seconds. Check API and database service status.' ;;
		'error.refreshDb') printf '%s' 'Could not recreate the database service without initial setup credentials, or it did not become healthy within 300 seconds. Check database service status and Docker resources; keep database storage.' ;;
		'error.releaseFiles') printf '%s' 'Required release files are missing or unreadable. Extract the complete release into a readable folder and run it there.' ;;
		'error.removeMigration') printf '%s' 'Could not remove the completed migration container. Check its state and Docker access. Database storage has not been deleted.' ;;
		'error.saveConfiguration') printf '%s' 'Could not save .env. Check installation folder write permissions and free disk space. An existing file will not be overwritten.' ;;
		'error.settings') printf '%s' 'Could not read the saved installation settings. Check that .env exists, its APP_ORIGIN and HTTP_PORT are valid, and Docker can read the installation folder. Do not share secret values.' ;;
		'error.setup') printf '%s' 'The setup input container failed or input was cancelled. Configuration may already have been saved. Check the message above, use an interactive terminal, and confirm folder write permissions.' ;;
		'error.start') printf '%s' 'Database initialization or service startup failed, or services did not become healthy within 300 seconds. Check the migration job and service status, HTTP port conflicts and Docker resources. The underlying cause could not be determined safely.' ;;
		'error.stoppedShell') printf '%s' 'Installation stopped. Configuration and data are retained. Do not delete .env or database storage to retry.' ;;
		'error.stoppedWindows') printf '%s' 'Installation stopped. Do not delete .env or database storage to retry. No secrets are displayed.' ;;
		'error.terminal') printf '%s' 'Setup requires an interactive terminal for hidden password input. Run the installer directly in a terminal, without piping or redirecting input/output.' ;;
		'error.timeout') printf '%s' 'The check did not complete within its time limit. Check Docker responsiveness and network access, then retry. Existing settings and data have been preserved.' ;;
		'error.unexpected') printf '%s' 'An unexpected installer error occurred. Its underlying cause could not be determined safely. Use the stopped stage shown above to check file permissions and Docker access. Do not share .env or unredacted diagnostics.' ;;
		'error.workspace') printf '%s' 'The container could not read the release or write to this installation folder. Check Docker file sharing, mount permissions and the selected Docker context. Remote Docker must have access to the same installation files.' ;;
		'error.writeFolder') printf '%s' 'The installation folder could not create, write, rename, delete or protect test files. Choose a writable folder and check its ownership, permissions and security software restrictions.' ;;
		'exit.prompt') printf '%s' 'Press Enter to close' ;;
		'frame.separator') printf '%s' '  ================================================' ;;
		'gender.female') printf '%s' 'Female' ;;
		'gender.male') printf '%s' 'Male' ;;
		'gender.unspecified') printf '%s' 'Unspecified' ;;
		'input.defaultsNotice') printf '%s' 'Values in [] are defaults. Press Enter to accept the default values. You can change these after signing in.' ;;
		'input.invalid') printf '%s' 'Invalid value. Please try again.' ;;
		'input.selectNumber') printf '%s' 'Select a number' ;;
		'language.notice') printf '%s' 'Your chosen language is also your initial application language. Change it in Personal settings > Localization.' ;;
		'locale.code') printf '%s' 'en' ;;
		'locale.name') printf '%s' 'English' ;;
		'locale.prompt') printf '%s' 'Language' ;;
		'password.confirm') printf '%s' 'Confirm password: ' ;;
		'password.invalid') printf '%s' 'Password does not meet the requirements.' ;;
		'password.mismatch') printf '%s' 'Passwords do not match.' ;;
		'password.notice') printf '%s' 'Choose your sign-in password: 12–1024 characters, including uppercase, lowercase and a number. Input is hidden.' ;;
		'password.prompt') printf '%s' 'Password: ' ;;
		'preflight.fail') printf '%s' '[FAIL] {1}' ;;
		'preflight.pass') printf '%s' '[OK] {1}' ;;
		'preflight.skip') printf '%s' '[SKIP] {1}: prerequisite checks failed.' ;;
		'preflight.warning') printf '%s' '[WARNING] {1}' ;;
		'profile.birthDate') printf '%s' 'Birth date (temporary example, YYYY-MM-DD)' ;;
		'profile.email') printf '%s' 'Email (temporary example)' ;;
		'profile.firstName') printf '%s' 'First name' ;;
		'profile.gender') printf '%s' 'Gender' ;;
		'profile.lastName') printf '%s' 'Last name' ;;
		'profile.notice') printf '%s' 'Change these personal details later in Personal settings > Profile.' ;;
		'progress.compact') printf '%s' '[{1}/7] {2} S[{3}]{4}% T[{5}]{6}% {7}' ;;
		'progress.done') printf '%s' '[Complete]' ;;
		'progress.line') printf '%s' '[{1}/7] {2} | Stage [{3}] {4}% | Overall [{5}] {6}% {7}' ;;
		'progress.notice') printf '%s' 'Seven stages. Installation may take a few minutes.' ;;
		'progress.running') printf '%s' 'Running' ;;
		'progress.stopped') printf '%s' '[{1}/7] {2}' ;;
		'progress.stoppedState') printf '%s' '[Stopped]' ;;
		'prompt.default') printf '%s' '{1} [{2}]: ' ;;
		'prompt.option') printf '%s' '  {1}. {2}' ;;
		'prompt.selection') printf '%s' '{1}:' ;;
		'prompt.styledDefault') printf '%s' '{1} {2}: ' ;;
		'samples.no') printf '%s' 'Do not add' ;;
		'samples.prompt') printf '%s' 'Sample data' ;;
		'samples.yes') printf '%s' 'Add' ;;
		'stage.build') printf '%s' 'Build images' ;;
		'stage.check') printf '%s' 'Check startup' ;;
		'stage.cleanup') printf '%s' 'Remove setup credentials' ;;
		'stage.environment') printf '%s' 'Environment checks' ;;
		'stage.final') printf '%s' 'Final checks' ;;
		'stage.setup') printf '%s' 'Configure installation' ;;
		'stage.start') printf '%s' 'Initialize and start' ;;
		'title') printf '%s' 'INSTALLATION' ;;
		'title.banner') printf '%s' '     SME Portal Hub — INSTALLATION' ;;
		'warning.book.cover') printf '%s' 'Some sample titles were registered without a cover. Retry using Refresh openBD details in the book details. Affected ISBNs are recorded in the migration container logs.' ;;
		'warning.book.lookup') printf '%s' 'Some sample book titles could not be retrieved and were skipped. Register them later using ISBN search on Books. Affected ISBNs are recorded in the migration container logs.' ;;
		'warning.disk') printf '%s' 'Recommended free space is {1} GiB. Current free space is {2} GiB.' ;;
		'warning.diskUnknown') printf '%s' 'The current free space could not be checked. Recommended free space is {1} GiB.' ;;
		'warning.holidayJP') printf '%s' 'The Japanese Cabinet Office holiday data could not be retrieved. After signing in, open Work calendars and select Refresh holidays.' ;;
		'warning.holidayUS') printf '%s' 'The U.S. Office of Personnel Management (OPM) federal holiday data could not be retrieved. After signing in, open Work calendars and select Refresh holidays.' ;;
		'warning.memory') printf '%s' 'Recommended Docker memory is {1} GiB. Current Docker memory is {2} GiB.' ;;
		'warning.memoryUnknown') printf '%s' 'Docker memory could not be checked. Recommended Docker memory is {1} GiB.' ;;
		'warning.publicUrl') printf '%s' 'Local startup succeeded, but the application URL could not be verified from the installer. Check client DNS, firewall and certificate trust settings.' ;;
		*) return 1 ;;
	esac
}
